    svg.appendChild(el("rect",{x:x-cw/2,y:bodyTop,width:cw,height:bodyH,fill:fill}));
  });

  // Volume bars
  candles.forEach(function(d,i){
    var x = xS(i);
    var bull = d.c >= d.o;
    var fill = bull ? "#3a7a55" : "#8a3030";
    var barH = (d.vol/maxVol)*volH;
    var barY = margin.top+mainH+gap+volH - barH;
