  // Volume label
  svg.appendChild(txt("VOL",{x:margin.left+4,y:margin.top+mainH+gap+10,"font-size":"7.5","font-weight":"700","fill":"#bbb","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}));

