  svg.appendChild(txt("Conflict",{x:confX+3,y:margin.top+14,"font-size":"7","font-weight":"700","fill":"#1a3560","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}));

  // Ceasefire Jun 15 = index 24
  var ceaseX = xS(24);
