  svg.appendChild(txt("Ceasefire",{x:ceaseX-3,y:margin.top+14,"text-anchor":"end","font-size":"7","font-weight":"700","fill":"#1a3560","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}));

